CREATE TABLE billing_plans (plan_code TEXT PRIMARY KEY, title TEXT NOT NULL, features_json TEXT NOT NULL, student_limit INTEGER NOT NULL CHECK(student_limit>=0), warning_quota INTEGER NOT NULL CHECK(warning_quota>=0), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE billing_quotes (quote_id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(actor_id), plan_code TEXT NOT NULL REFERENCES billing_plans(plan_code), inputs_json TEXT NOT NULL, subtotal_minor INTEGER NOT NULL CHECK(subtotal_minor>=0), discount_minor INTEGER NOT NULL CHECK(discount_minor>=0), credit_minor INTEGER NOT NULL CHECK(credit_minor>=0), total_minor INTEGER NOT NULL CHECK(total_minor>=0), currency TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE billing_orders (order_id TEXT PRIMARY KEY, quote_id TEXT NOT NULL REFERENCES billing_quotes(quote_id), account_id TEXT NOT NULL REFERENCES accounts(actor_id), state TEXT NOT NULL CHECK(state IN ('PENDING','PAID','FAILED','CANCELLED','EXPIRED')), gateway TEXT NOT NULL, mode TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, checkout_ref TEXT, amount_minor INTEGER NOT NULL CHECK(amount_minor>=0), currency TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE payment_events (event_id TEXT PRIMARY KEY, order_id TEXT REFERENCES billing_orders(order_id), gateway TEXT NOT NULL, normalized_hash TEXT NOT NULL UNIQUE, signature_valid INTEGER NOT NULL CHECK(signature_valid IN (0,1)), payload_redacted TEXT NOT NULL, received_at TEXT NOT NULL, processed_state TEXT NOT NULL);
CREATE TABLE billing_receipts (receipt_id TEXT PRIMARY KEY, order_id TEXT NOT NULL UNIQUE REFERENCES billing_orders(order_id), account_id TEXT NOT NULL REFERENCES accounts(actor_id), receipt_json TEXT NOT NULL, issued_at TEXT NOT NULL);
CREATE TRIGGER billing_receipt_paid_only BEFORE INSERT ON billing_receipts WHEN (SELECT state FROM billing_orders WHERE order_id=NEW.order_id)!='PAID' BEGIN SELECT RAISE(ABORT,'receipt requires paid order'); END;
CREATE TABLE licenses (license_id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(actor_id), key_version TEXT NOT NULL, payload TEXT NOT NULL, signature TEXT NOT NULL, expires_at TEXT, created_at TEXT NOT NULL, revoked_at TEXT);
CREATE TABLE entitlements (entitlement_id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(actor_id), plan_code TEXT NOT NULL REFERENCES billing_plans(plan_code), features_json TEXT NOT NULL, student_limit INTEGER NOT NULL CHECK(student_limit>=0), warning_quota INTEGER NOT NULL CHECK(warning_quota>=0), effective_at TEXT NOT NULL, expires_at TEXT, grace_until TEXT, source_order TEXT REFERENCES billing_orders(order_id), created_at TEXT NOT NULL);
